 * Splits raw stdin text into the three documents (mine, base, theirs) the
 * CLI operates on.
 */

/** Thrown when stdin does not hold exactly three `%%%`-separated documents. */
export class InputFormatError extends Error {}

/**
 * Splits `text` on newlines, drops the empty tail a trailing newline leaves,
 * and groups the resulting lines into documents separated by lines that are
 * exactly `%%%`. Throws {@link InputFormatError} unless there are exactly
 * three documents.
 */
export function parseDocuments(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') docs.push([])
    else docs[docs.length - 1].push(line)
  }

  if (docs.length !== 3) throw new InputFormatError('expected three parts separated by %%%')
  return docs
}
"}

