{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-0TMJz0/src/lcs.js","content":"/**
 * Longest-common-subsequence matching between a side document and the base
 * document, with the tie-breaking rule the task specifies: among equally
 * long subsequences, the one whose matches come earliest, found by
 * preferring to advance the base on ties.
 */

/**
 * Returns the list of matched index pairs `[baseIndex, sideIndex]`, in
 * increasing order, between `base` and `side`.
 */
function matchIndices(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Computes the changes between `base` and `side` as runs of base lines
 * `[baseStart, baseEnd)` replaced by side lines `[sideStart, sideEnd)`.
 * Runs where both spans are empty (a stretch of pure matches) are omitted.
 */
export function computeChanges(base, side) {
  const matches = matchIndices(base, side)
  const changes = []
  let prevBase = -1
  let prevSide = -1

  for (const [bi, si] of [...matches, [base.length, side.length]]) {
    const baseStart = prevBase + 1
    const baseEnd = bi
    const sideStart = prevSide + 1
    const sideEnd = si
    if (baseEnd > baseStart || sideEnd > sideStart) {
      changes.push({ baseStart, baseEnd, sideStart, sideEnd })
    }
    prevBase = bi
    prevSide = si
  }

  return changes
}
"}

